47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
105	        this.clinicService.saveOwner(owner, sharesHousehold);
106	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
107	        headers.setLocation(UriComponentsBuilder.newInstance()
108	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
109	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
115	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
116	        if (currentOwner == null) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        currentOwner.setAddress(ownerFieldsDto.getAddress());
120	        currentOwner.setCity(ownerFieldsDto.getCity());
121	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
122	        currentOwner.setLastName(ownerFieldsDto.getLastName());
123	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
124	        currentOwner.setEmail(ownerFieldsDto.getEmail());
125	        this.clinicService.saveOwner(currentOwner);
126	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Transactional
131	    @Override
132	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        this.clinicService.deleteOwner(owner);
138	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        HttpHeaders headers = new HttpHeaders();
149	        Pet pet = petMapper.toPet(petFieldsDto);
150	        owner.setId(ownerId);
151	        pet.setOwner(owner);
152	        pet.getType().setName(null);
153	        this.clinicService.savePet(pet);
154	        PetDto petDto = petMapper.toPetDto(pet);
155	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
156	            .buildAndExpand(pet.getId()).toUri());
157	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
163	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
164	        if (currentOwner != null) {
165	            Pet currentPet = this.clinicService.findPetById(petId);
166	            if (currentPet != null) {
167	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
168	                currentPet.setName(petFieldsDto.getName());
169	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
170	                this.clinicService.savePet(currentPet);
171	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
172	            }
173	        }
174	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
180	        HttpHeaders headers = new HttpHeaders();
181	        Visit visit = visitMapper.toVisit(visitFieldsDto);
182	        Pet pet = new Pet();
183	        pet.setId(petId);
184	        visit.setPet(pet);
185	        this.clinicService.saveVisit(visit);
186	        VisitDto visitDto = visitMapper.toVisitDto(visit);
187	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
188	            .buildAndExpand(visit.getId()).toUri());
189	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
190	    }
191	
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner != null) {
198	            Pet pet = owner.getPet(petId);
199	            if (pet != null) {
200	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	}
