45	    @Autowired
46	    public void configureGlobal(AuthenticationManagerBuilder auth) throws Exception {
47	        // @formatter:off
48	        auth
49	            .jdbcAuthentication()
50	                .dataSource(dataSource)
51	                .usersByUsernameQuery("select username,password,enabled from users where username=?")
52	                .authoritiesByUsernameQuery("select username,role from roles where username=?");
53	        // @formatter:on
54	    }
55	}
